update item
set view_count = view_count + 1
where item_id = #{itemId}

update item
set item_status_id = #{itemStatus}
where item_id = #{itemId}

mapper.select:
select i.item_id, i.item_name, i.item_info, i.post_date, i.update_date, i.donation_flag, i.price, i.category_id, i.price_negotiation_yn, i.item_status_id, i.view_count, (select count(*) from favorite f where f.item_id = i.item_id) as like_count FROM item as i WHERE member_id IN ( SELECT member_id FROM member WHERE region_id IN ( SELECT region_id FROM ( SELECT region_id, (6371*ACOS(COS(RADIANS((SELECT lati_tude FROM region WHERE region_id = #{regionId}))) *COS(RADIANS(lati_tude))*COS(RADIANS(longi_tude)-RADIANS((SELECT longi_tude FROM region WHERE region_id = #{regionId}))) +SIN(RADIANS((SELECT lati_tude FROM region WHERE region_id = #{regionId})))*SIN(RADIANS(lati_tude)))) AS distance FROM region) AS a
WHERE distance <= 6
) )

select i.item_id, i.item_name, i.item_info, i.post_date, i.update_date, i.donation_flag, i.price, i.category_id, i.price_negotiation_yn, i.item_status_id, i.view_count, (select count(*) from favorite f where f.item_id = i.item_id) as like_count FROM item as i WHERE member_id IN ( SELECT member_id FROM member WHERE region_id IN ( SELECT region_id FROM ( SELECT region_id, (6371*ACOS(COS(RADIANS((SELECT lati_tude FROM region WHERE region_id = #{regionId}))) *COS(RADIANS(lati_tude))*COS(RADIANS(longi_tude)-RADIANS((SELECT longi_tude FROM region WHERE region_id = #{regionId}))) +SIN(RADIANS((SELECT lati_tude FROM region WHERE region_id = #{regionId})))*SIN(RADIANS(lati_tude)))) AS distance FROM region) AS a
WHERE distance <= 6
) )
AND item_name LIKE CONCAT('%',#{itemName},'%')
AND item_status_id = #{itemStatus}

